		List<String> generic = genericRows(query, null, null);
		assertThat(generic)
				.as("interpreted engine: only s2's optional value passes the filter")
				.containsExactly("l=\"l2\"|o=\"7\"^^<http://www.w3.org/2001/XMLSchema#int>|s=http://example.com/s2");
		assertThat(rows(query, null, null))
				.as("native rows must match the interpreted engine without entry bindings")
				.isEqualTo(generic);
